<script lang="ts">
  import type {Database,DatabaseViewConfig,Page} from "@/features/notion-ui/variants/database/types"; import {computeCalc} from "@/features/notion-ui/variants/database/lib/calcAggregate"; import {visibleProps} from "../../lib/view-core";
  let {db,view,rows,onOpenRow}= $props<{db:Database;view:DatabaseViewConfig;rows:Page[];onOpenRow?:(id:string)=>void}>(); let props=$derived(visibleProps(db,view)); let kpis=$derived((view.dashboardKPIs?.length?view.dashboardKPIs:props.filter(p=>p.type==="number").slice(0,3).map(p=>p.id)).map(id=>db.properties.find(p=>p.id===id)).filter(Boolean)); let recent=$derived([...rows].sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,view.dashboardRecentLimit??5));
</script>
<div class="space-y-4 p-4"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-lg border p-3"><span class="text-[10px] uppercase text-muted-foreground">Rows</span><strong class="mt-1 block text-2xl">{rows.length}</strong></div>{#each kpis as prop (prop!.id)}<div class="rounded-lg border p-3"><span class="text-[10px] uppercase text-muted-foreground">{prop!.name}</span><strong class="mt-1 block text-2xl">{computeCalc(rows,prop!,"sum")}</strong><span class="text-[10px] text-muted-foreground">sum</span></div>{/each}</div><section><h4 class="mb-2 text-xs font-semibold uppercase text-muted-foreground">Recently edited</h4><div class="divide-y rounded-lg border">{#each recent as row (row.id)}<button class="flex w-full items-center justify-between px-3 py-2 text-left text-sm hover:bg-muted" onclick={()=>onOpenRow?.(row.id)}><span>{row.icon} {row.title||"Untitled"}</span><time class="text-[10px] text-muted-foreground">{new Date(row.updatedAt).toLocaleDateString()}</time></button>{/each}</div></section></div>
